using System;

namespace CrownTowersClub.Models
{
    /// <summary>
    /// Represents a specific yearly billing cycle for a Membership.
    /// Maps directly to the [dbo].[MembershipTerms] table.
    /// </summary>
    public sealed class MembershipTerm
    {
        /* ============================================================
           1. Database Columns (Maps to dbo.MembershipTerms)
           ============================================================ */

        /// <summary>
        /// Primary Key. Auto-generated by the database (IDENTITY).
        /// </summary>
        public int MembershipTermId { get; set; }

        /// <summary>
        /// Foreign Key linking to the parent Membership record.
        /// </summary>
        public int MembershipId { get; set; }

        /// <summary>
        /// The year this term covers (e.g., 2026, 2027).
        /// Changed from 'short' to 'int' for safe Dapper mapping.
        /// </summary>
        public int MembershipYear { get; set; }

        /// <summary>
        /// When the term begins (typically Jan 1st of the year).
        /// </summary>
        public DateTime StartDate { get; set; }

        /// <summary>
        /// When the term ends (typically Dec 31st of the year).
        /// </summary>
        public DateTime EndDate { get; set; }

        /// <summary>
        /// The amount the member is required to pay for this year.
        /// </summary>
        public decimal FeeAmount { get; set; }

        /// <summary>
        /// The date by which the payment must be made.
        /// If the payment is late, the term is marked as 'Expired'.
        /// </summary>
        public DateTime DueDate { get; set; }

        /// <summary>
        /// The current billing status of this term.
        /// Valid values: 'Pending Payment', 'Active', 'Expired'.
        /// </summary>
        public string TermStatus { get; set; }

        /// <summary>
        /// Audit field. When this term was generated.
        /// </summary>
        public DateTime CreatedAt { get; set; }

        /// <summary>
        /// Audit field. When this term was last modified (e.g., when payment was recorded).
        /// </summary>
        public DateTime? UpdatedAt { get; set; }
    }
}